### Honor cached revocation when verifying the peer signer

**Severity:** `high`

The custom signer chain currently sets `X509RevocationMode.NoCheck`, so it cannot reject a certificate whose revocation is already present in the machine cache. Keep this path network-free by using offline revocation, allowing only the expected unavailable or offline status flags, and still rejecting every known revocation or other chain error.

```suggestion
                using var chain = new X509Chain();
                chain.ChainPolicy.RevocationMode = X509RevocationMode.Offline;
                chain.ChainPolicy.TrustMode = X509ChainTrustMode.CustomRootTrust;

                // Check lifetime at the same current time or validated timestamp that Windows used.
                chain.ChainPolicy.VerificationTime = verificationTime;
                chain.ChainPolicy.ApplicationPolicy.Add(new Oid("1.3.6.1.5.5.7.3.3"));
                chain.ChainPolicy.VerificationFlags =
                    X509VerificationFlags.IgnoreEndRevocationUnknown |
                    X509VerificationFlags.IgnoreCertificateAuthorityRevocationUnknown |
                    X509VerificationFlags.IgnoreRootRevocationUnknown;

                var rootCertificates = roots.Certificates;
                try
                {
                    chain.ChainPolicy.CustomTrustStore.AddRange(rootCertificates);

                    if (TryGetEmbeddedPkcs7Store(imagePath, out var store, out var message))
                    {
                        using (store)
                        using (message)
                        using (var embeddedStore = new X509Store(store.DangerousGetHandle()))
                        {
                            var extraCertificates = embeddedStore.Certificates;
                            try
                            {
                                chain.ChainPolicy.ExtraStore.AddRange(extraCertificates);
                                if (!chain.Build(imageSigner) && !HasOnlyAllowedRevocationStatuses(chain.ChainStatus))
                                {
                                    return false;
                                }

                                signer = X509CertificateLoader.LoadCertificate(imageSigner.RawData);
                                return true;
                            }
                            finally
                            {
                                DisposeCertificates(extraCertificates);
                            }
                        }
                    }

                    if (!chain.Build(imageSigner) && !HasOnlyAllowedRevocationStatuses(chain.ChainStatus))
                    {
                        return false;
                    }

                    signer = X509CertificateLoader.LoadCertificate(imageSigner.RawData);
                    return true;
                }
                finally
                {
                    DisposeCertificates(rootCertificates);
                }
            }
            catch (CryptographicException)
            {
                signer?.Dispose();
                signer = null;
                return false;
            }
        }

        private static void DisposeCertificates(X509Certificate2Collection certificates)
        {
            foreach (var certificate in certificates)
            {
                certificate.Dispose();
            }
        }

        private static bool HasOnlyAllowedRevocationStatuses(X509ChainStatus[] statuses)
        {
            foreach (var status in statuses)
            {
                var disallowedFlags = status.Status & ~(X509ChainStatusFlags.NoError | X509ChainStatusFlags.RevocationStatusUnknown | X509ChainStatusFlags.OfflineRevocation);
                if (disallowedFlags != X509ChainStatusFlags.NoError)
                {
                    return false;
                }
            }

            return true;
        }
```

### Back off rejected clients and throttle both retry log paths

**Severity:** `medium`

A rejected or pipe-squatting caller can currently drive this loop continuously: rejected connections immediately retry, while both rejection and exception paths emit a log on every attempt. Add a cancellation-aware delay after rejection and rate-limit each log path independently so the server remains responsive without sustained CPU or log growth.

```suggestion
            _ = Task.Run(
                async () =>
                {
                    DateTime lastRejectedConnectionLogAt = DateTime.MinValue;
                    DateTime lastServerErrorLogAt = DateTime.MinValue;

                    while (!cancellationToken.IsCancellationRequested)
                    {
                        try
                        {
                            using var serverChannel = RestrictedNamedPipeServer.Create(pipeName, allowedUser);
                            await serverChannel.WaitForConnectionAsync(cancellationToken);

                            var rejectionReason = verifyClientConnection(serverChannel);
                            if (!string.IsNullOrEmpty(rejectionReason))
                            {
#if !MM_HELPER
                                var utcNow = DateTime.UtcNow;
                                if (utcNow - lastRejectedConnectionLogAt >= TimeSpan.FromSeconds(30))
                                {
                                    Logger.Log($"Rejected Settings IPC client: {rejectionReason}");
                                    lastRejectedConnectionLogAt = utcNow;
                                }
#endif
                                if (serverChannel.IsConnected)
                                {
                                    serverChannel.Disconnect();
                                }

                                await Task.Delay(250, cancellationToken);
                                continue;
                            }

                            var taskRpc = JsonRpc.Attach(serverChannel, new T());
                            await taskRpc.Completion;
                        }
                        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
                        {
                            break;
                        }
                        catch (Exception e)
                        {
                            serverErrorObserver?.Invoke(e);
#if MM_HELPER
                            _ = e;
#else
                            var utcNow = DateTime.UtcNow;
                            if (utcNow - lastServerErrorLogAt >= TimeSpan.FromSeconds(30))
                            {
                                Logger.Log(e);
                                lastServerErrorLogAt = utcNow;
                            }
#endif
                            if (!cancellationToken.IsCancellationRequested)
                            {
                                await Task.Delay(250);
                            }
                        }
                    }
                },
                cancellationToken);
```

### Keep generated certificate fixtures inside issuer validity

**Severity:** `medium`

These helpers recompute `UtcNow.AddDays(7)` for each child after its issuer was created, which can make the child expire slightly later than the issuer and intermittently invalidate the chain. Derive each child expiration from its issuer so the generated hierarchy is deterministic and always valid.

```suggestion
        private static X509Certificate2 CreateIntermediateCertificate(X509Certificate2 root, RSA intermediateKey)
        {
            var notBefore = DateTimeOffset.UtcNow.AddDays(-1);
            var notAfter = root.NotAfter.ToUniversalTime().AddMinutes(-1);
            var request = new CertificateRequest(
                "CN=MWB IPC Test Intermediate",
                intermediateKey,
                HashAlgorithmName.SHA256,
                RSASignaturePadding.Pkcs1);
            request.CertificateExtensions.Add(new X509BasicConstraintsExtension(true, false, 0, true));
            request.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.KeyCertSign | X509KeyUsageFlags.CrlSign, true));
            request.CertificateExtensions.Add(new X509SubjectKeyIdentifierExtension(request.PublicKey, false));

            using var intermediate = request.Create(root, notBefore, notAfter, RandomNumberGenerator.GetBytes(16));
            return intermediate.CopyWithPrivateKey(intermediateKey);
        }

        private static X509Certificate2 CreateCodeSigningLeafCertificate(X509Certificate2 intermediate)
        {
            using var leafKey = RSA.Create(2048);
            var notBefore = DateTimeOffset.UtcNow.AddDays(-1);
            var notAfter = intermediate.NotAfter.ToUniversalTime().AddMinutes(-1);
            var request = new CertificateRequest(
                "CN=Microsoft Corporation Unit Test",
                leafKey,
                HashAlgorithmName.SHA256,
                RSASignaturePadding.Pkcs1);
            request.CertificateExtensions.Add(new X509BasicConstraintsExtension(false, false, 0, true));
            request.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.DigitalSignature, true));
            request.CertificateExtensions.Add(new X509SubjectKeyIdentifierExtension(request.PublicKey, false));

            var enhancedKeyUsage = new OidCollection
            {
                new Oid("1.3.6.1.5.5.7.3.3"),
            };
            request.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(enhancedKeyUsage, true));

            return request.Create(intermediate, notBefore, notAfter, RandomNumberGenerator.GetBytes(16));
        }
```
